"""Единый реестр иллюстраций справки: HTML, PDF и сценарий пересъёмки используют эти ключи."""
from dataclasses import dataclass


@dataclass(frozen=True)
class Screenshot:
    key: str
    title: str
    alt: str
    legend: tuple[str, ...]

    @property
    def filename(self):
        return f'{self.key}.png'

    @property
    def static_path(self):
        return f'help/images/{self.filename}'


def _shot(key, title, *legend):
    return Screenshot(key, title, f'{title}. Пронумерованные стрелки показывают элементы интерфейса.', tuple(legend))


